func ReadDayEntryLoadMessages(values []ReadDayEntry, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !ReadDayEntryLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// ReaderSpendReset restores ReaderSpend's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ReaderSpendReset(value *ReaderSpend) {
	value.Reads = 0
	value.Priced = 0
	clear(value.Usd[:])
	value.UsdLength = 0
	value.HourPriced = 0
	clear(value.HourUsd[:])
	value.HourUsdLength = 0
	value.Tokens = 0
}

func ReaderSpendMeasureBody(value *ReaderSpend, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ReaderSpendSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ReaderSpendMeasure(value *ReaderSpend) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !ReaderSpendSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func ReaderSpendMeasureReason(value *ReaderSpend) (int64, error) {
	size := ReaderSpendMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
