func ReaderSpendLoadMessages(values []ReaderSpend, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !ReaderSpendLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// ReaderSpendEntryReset restores ReaderSpendEntry's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ReaderSpendEntryReset(value *ReaderSpendEntry) {
	clear(value.Reader[:])
	value.ReaderLength = 0
	ReaderSpendReset(&value.Spend)
}

func ReaderSpendEntryMeasureBody(value *ReaderSpendEntry, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ReaderSpendEntrySaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ReaderSpendEntryMeasure(value *ReaderSpendEntry) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !ReaderSpendEntrySaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func ReaderSpendEntryMeasureReason(value *ReaderSpendEntry) (int64, error) {
	size := ReaderSpendEntryMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func ReaderSpendEntrySaveBody(w *TableWriter, value *ReaderSpendEntry) bool {
	{
		if value.ReaderLength < 0 || value.ReaderLength > 64 {
			return false
		}
		if value.ReaderLength > 0 {
			if ref := w.Ids.refAtHit(46, 0x196268f31c5eca56); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.ReaderLength < 0 || value.ReaderLength > 64 {
				return false
			}
			if !w.putLebPair(uint64(value.ReaderLength)) {
				w.putLebWide(uint64(value.ReaderLength))
			}
			w.Raw(value.Reader[:value.ReaderLength])
		}
	}
	{
		mark := w.Ids.Count
		ref := w.Ids.refAtHit(62, 0x22704b8aa0119e73)
		start := w.Ids.Count
		n := ReaderSpendMeasureBody(&value.Spend, w.Ids)
		if n < 0 || w.Ids.Overflow {
			return false
		}
		if n > 1 {
			if w.Measuring {
				w.Advance(tableLebBytes(ref) + 1 + tableLebBytes(uint64(n)) + n)
			} else {
				w.Ids.Truncate(start)
				if !w.headerPair(ref, 13) {
					w.headerRest(ref, 13)
				}
				if !w.putLebPair(uint64(n)) {
					w.putLebWide(uint64(n))
				}
				if !ReaderSpendSaveBody(w, &value.Spend) {
					return false
				}
			}
		} else {
			w.Ids.Truncate(mark)
		}
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}

func ReaderSpendEntrySave(value *ReaderSpendEntry, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !ReaderSpendEntrySaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func ReaderSpendEntryLoadBody(r *TableReader, value *ReaderSpendEntry) bool {
	ReaderSpendEntryReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x196268f31c5eca56: // reader
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Reader[:])
				value.ReaderLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 64 {
				keep = tableUtf8Clamp(sub.Buffer, 64)
				r.Report.Clamped++
			}
			clear(value.Reader[:])
			copy(value.Reader[:keep], sub.Buffer)
			value.ReaderLength = int32(keep)
		case 0x22704b8aa0119e73: // spend
			if kind != 13 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			ReaderSpendLoadBody(&sub, &value.Spend)
			if sub.Offset != int64(len(sub.Buffer)) {
				r.Report.Malformed = true
				ReaderSpendReset(&value.Spend)
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

// ReaderSpendEntry also carries the FIXED form (form 3): ReaderSpendEntryFixedLoad reads that one and
// names a form-1 file `previous_form`. This Load is the VARIABLE form's entry
// point and reads form 1, whether or not the table was DECLARED fixed
// (docs/SPEC-TABLES.md §3.4, §15).
func ReaderSpendEntryLoad(value *ReaderSpendEntry, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpen(data, report)
	report.Verdict = verdict
	report.Reason = ""
	if verdict == TableOpenRefused {
		report.Reason = "unsupported wire form"
		if len(data) > 0 && data[0] == 2 {
			report.Reason = "message form requires an announced vocabulary and a message reader"
		}
	}
	if verdict != TableOpenOk {
		ReaderSpendEntryReset(value)
		if verdict == TableOpenDamaged {
			report.Malformed = true
		}
		return false
	}
	// The root read answers its own early end after the walk, not before it.
	// A body that returned at its zero reference left the cursor on the byte
	// after that reference. Every field leaves the cursor where skip would, so
	// r.Offset != len(r.Buffer) is the old EndsEarly on the true path.
	// Nothing is decoded on the damaged path: the value goes back to defaults
	// and the report goes back to what the caller handed in, so an early end
	// counts no unknown, no kind mismatch and no clamp — as when the framing
	// walk refused before the reader had seen one byte.
	before := *report
	if !ReaderSpendEntryLoadBody(&r, value) {
		// The reading walk stops on rules the framing walk has no opinion about
		// — a reserved id in a file body is the one that matters — so a body
		// that stopped is still asked the framing question from the start of
		// the body, and a body whose framing ends early is damage whatever else
		// was wrong with it.
		probe := r
		probe.Offset = 0
		if probe.EndsEarly() {
			ReaderSpendEntryReset(value)
			*report = before
			report.Malformed = true
			report.Verdict = TableOpenDamaged
			return false
		}
		report.Verdict = TableOpenBodyStopped
		return false
	}
	if r.Offset != int64(len(r.Buffer)) {
		ReaderSpendEntryReset(value)
		*report = before
		report.Malformed = true
		report.Verdict = TableOpenDamaged
		return false
	}
	return true
}

