func CostReconcileRecordLoadMessages(values []CostReconcileRecord, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !CostReconcileRecordLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// TierCountEntryReset restores TierCountEntry's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func TierCountEntryReset(value *TierCountEntry) {
	clear(value.Tier[:])
	value.TierLength = 0
	value.N = 0
}

func TierCountEntryMeasureBody(value *TierCountEntry, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !TierCountEntrySaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func TierCountEntryMeasure(value *TierCountEntry) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !TierCountEntrySaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func TierCountEntryMeasureReason(value *TierCountEntry) (int64, error) {
	size := TierCountEntryMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func TierCountEntrySaveBody(w *TableWriter, value *TierCountEntry) bool {
	{
		if value.TierLength < 0 || value.TierLength > 32 {
			return false
		}
		if value.TierLength > 0 {
			if ref := w.Ids.refAtHit(54, 0x1e6f84ef2eb65989); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.TierLength < 0 || value.TierLength > 32 {
				return false
			}
			if !w.putLebPair(uint64(value.TierLength)) {
				w.putLebWide(uint64(value.TierLength))
			}
			w.Raw(value.Tier[:value.TierLength])
		}
	}
	{
		if value.N != 0 {
			if ref := w.Ids.refAtHit(318, 0xaf63e34c8601f871); !w.headerPair(ref, 4) {
				w.headerRest(ref, 4)
			}
			w.Put32(uint32(value.N))
		}
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}

func TierCountEntrySave(value *TierCountEntry, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !TierCountEntrySaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

