func CostTierEntryLoadMessages(values []CostTierEntry, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !CostTierEntryLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// TierCostsReset restores TierCosts's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func TierCostsReset(value *TierCosts) {
	for i := range value.Tiers {
		TierCountEntryReset(&value.Tiers[i])
	}
	value.TiersCount = 0
	clear(value.PerLanded[:])
	value.PerLandedLength = 0
	for i := range value.CostByTier {
		CostTierEntryReset(&value.CostByTier[i])
	}
	value.CostByTierCount = 0
	clear(value.TotalCost[:])
	value.TotalCostLength = 0
	clear(value.TotalUsd[:])
	value.TotalUsdLength = 0
	clear(value.LandedUsd[:])
	value.LandedUsdLength = 0
	clear(value.WorkCost[:])
	value.WorkCostLength = 0
	clear(value.ReadCost[:])
	value.ReadCostLength = 0
	clear(value.DecideCost[:])
	value.DecideCostLength = 0
	value.DecideUnpriced = 0
	value.DroppedCards = 0
	value.CarriedCards = 0
	value.ReadTokens = 0
	for i := range value.ReadsToday {
		ReadDayEntryReset(&value.ReadsToday[i])
	}
	value.ReadsTodayCount = 0
	value.UnpricedRuns = 0
	value.ReadsNoTokens = 0
	for i := range value.Readers {
		ReaderSpendEntryReset(&value.Readers[i])
	}
	value.ReadersCount = 0
	clear(value.InFlight[:])
	value.InFlightLength = 0
	clear(value.Unreconciled[:])
	value.UnreconciledLength = 0
	for i := range value.Reconciles {
		CostReconcileRecordReset(&value.Reconciles[i])
	}
	value.ReconcilesCount = 0
}

func TierCostsMeasureBody(value *TierCosts, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !TierCostsSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func TierCostsMeasure(value *TierCosts) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !TierCostsSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func TierCostsMeasureReason(value *TierCosts) (int64, error) {
	size := TierCostsMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
