func LandingSaveMessageBody(w *TableMessageWriter, value *Landing) bool {
	{
		if value.At != 0 {
			w.Put(3, TableMessageRefBitsHere)
			tableMessageWriteScalar(&w.TableBitWriter, TableMessageShape{Kind: 5, Packing: 0, Bits: 64, Base: [2]uint64{0x0, 0x0}, Min: 0, Max: 0, QMin: math.Float32frombits(0x0), QDelta: math.Float32frombits(0x0), QCount: 0}, uint64(value.At), uint64(0))
		}
	}
	{
		if value.WorkerLength < 0 || value.WorkerLength > 135 {
			return false
		}
		if value.WorkerLength > 0 {
			w.Put(151, TableMessageRefBitsHere)
			if value.WorkerLength < 0 || value.WorkerLength > 135 {
				return false
			}
			w.Put(uint64(value.WorkerLength), 8)
			w.Raw(value.Worker[:value.WorkerLength])
		}
	}
	{
		if value.StreamLength < 0 || value.StreamLength > 128 {
			return false
		}
		if value.StreamLength > 0 {
			w.Put(45, TableMessageRefBitsHere)
			if value.StreamLength < 0 || value.StreamLength > 128 {
				return false
			}
			w.Put(uint64(value.StreamLength), 8)
			w.Raw(value.Stream[:value.StreamLength])
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func LandingMeasureMessages(values []*Landing, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !LandingSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func LandingSaveMessages(values []*Landing, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !LandingSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func LandingLoadMessageBody(r *TableMessageReader, value *Landing) bool {
	LandingReset(value)
	for {
		ref, ok := r.Bits.Get(r.Vocabulary.RefBits)
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		entry, ok := r.Vocabulary.Entry(ref)
		if !ok || entry.Id >= 0xfffffffffffffffd {
			r.Report.Malformed = true
			return false
		}
		switch entry.Id {
		case 0x089c4e07b545a968:
			{
				widened := false
				if entry.Shape.Kind != 5 || entry.Element.Kind != 0 {
					if entry.Element.Kind == 0 && tableKindWidens(entry.Shape.Kind, 5) {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					var raw [16]byte
					if !tableMessageReadScalar(&r.Bits, entry.Shape, &raw) {
						r.Report.Malformed = true
						return false
					}
					payload58 := TableReader{Buffer: raw[:], Report: &r.Report}
					if !payload58.Has(tableKindBytes(entry.Shape.Kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := payload58.Signed(entry.Shape.Kind)
						value.At = int64(v)
					}
				}
				if widened {
					r.Report.Widened++
				}
			}
		case 0xa51a677d5b590177:
			{
				widened := false
				if entry.Shape.Kind != 12 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok || !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					start := r.Bits.Offset / 8
					if !r.Bits.Skip(int64(n) * 8) {
						r.Report.Malformed = true
						return false
					}
					text := r.Bits.Buffer[start : start+int64(n)]
					if !tableUtf8Valid(text) {
						r.Report.Malformed = true
						return false
					}
					kept := tableUtf8Clamp(text, min(int64(n), int64(135)))
					if kept < int64(n) {
						r.Report.Clamped++
					}
					clear(value.Worker[:])
					copy(value.Worker[:], text[:kept])
					value.WorkerLength = int32(kept)
				}
				if widened {
					r.Report.Widened++
				}
			}
		case 0x4f6a36d8e8907985:
			{
				widened := false
				if entry.Shape.Kind != 12 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok || !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					start := r.Bits.Offset / 8
					if !r.Bits.Skip(int64(n) * 8) {
						r.Report.Malformed = true
						return false
					}
					text := r.Bits.Buffer[start : start+int64(n)]
					if !tableUtf8Valid(text) {
						r.Report.Malformed = true
						return false
					}
					kept := tableUtf8Clamp(text, min(int64(n), int64(128)))
					if kept < int64(n) {
						r.Report.Clamped++
					}
					clear(value.Stream[:])
					copy(value.Stream[:], text[:kept])
					value.StreamLength = int32(kept)
				}
				if widened {
					r.Report.Widened++
				}
			}
		default:
			r.Report.Unknown++
			if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}
func LandingLoadMessages(values []Landing, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !LandingLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// ArchivedFleetCardReset restores ArchivedFleetCard's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ArchivedFleetCardReset(value *ArchivedFleetCard) {
	clear(value.Row[:])
	value.RowLength = 0
	clear(value.Col[:])
	value.ColLength = 0
	value.At = 0
}

func ArchivedFleetCardMeasureBody(value *ArchivedFleetCard, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ArchivedFleetCardSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ArchivedFleetCardMeasure(value *ArchivedFleetCard) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !ArchivedFleetCardSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func ArchivedFleetCardMeasureReason(value *ArchivedFleetCard) (int64, error) {
	size := ArchivedFleetCardMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func ArchivedFleetCardSaveBody(w *TableWriter, value *ArchivedFleetCard) bool {
	{
		if value.RowLength < 0 || value.RowLength > 135 {
			return false
		}
		if value.RowLength > 0 {
			if ref := w.Ids.refAtHit(262, 0x8a0bc1196111ad9b); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.RowLength < 0 || value.RowLength > 135 {
				return false
			}
			if !w.putLebPair(uint64(value.RowLength)) {
				w.putLebWide(uint64(value.RowLength))
			}
			w.Raw(value.Row[:value.RowLength])
		}
	}
	{
		if value.ColLength < 0 || value.ColLength > 16 {
			return false
		}
		if value.ColLength > 0 {
			if ref := w.Ids.refAtHit(455, 0xf604f3190d016791); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.ColLength < 0 || value.ColLength > 16 {
				return false
			}
			if !w.putLebPair(uint64(value.ColLength)) {
				w.putLebWide(uint64(value.ColLength))
			}
			w.Raw(value.Col[:value.ColLength])
		}
	}
	{
		if value.At != 0 {
			if ref := w.Ids.refAtHit(14, 0x089c4e07b545a968); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			w.Put64(uint64(value.At))
		}
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}

func ArchivedFleetCardSave(value *ArchivedFleetCard, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !ArchivedFleetCardSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func ArchivedFleetCardLoadBody(r *TableReader, value *ArchivedFleetCard) bool {
	ArchivedFleetCardReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x8a0bc1196111ad9b: // row
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Row[:])
				value.RowLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 135 {
				keep = tableUtf8Clamp(sub.Buffer, 135)
				r.Report.Clamped++
			}
			clear(value.Row[:])
			copy(value.Row[:keep], sub.Buffer)
			value.RowLength = int32(keep)
		case 0xf604f3190d016791: // col
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Col[:])
				value.ColLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 16 {
				keep = tableUtf8Clamp(sub.Buffer, 16)
				r.Report.Clamped++
			}
			clear(value.Col[:])
			copy(value.Col[:keep], sub.Buffer)
			value.ColLength = int32(keep)
		case 0x089c4e07b545a968: // at
			if kind != 5 {
				if tableKindWidens(kind, 5) {
					if !r.Has(tableKindBytes(kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := r.Signed(kind)
						value.At = int64(v)
					}
					r.Report.Widened++
					break
				}
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(8) {
				r.Report.Malformed = true
				return false
			}
			{
				v := int64(r.Get64())
				value.At = int64(v)
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

// ArchivedFleetCard also carries the FIXED form (form 3): ArchivedFleetCardFixedLoad reads that one and
// names a form-1 file `previous_form`. This Load is the VARIABLE form's entry
// point and reads form 1, whether or not the table was DECLARED fixed
// (docs/SPEC-TABLES.md §3.4, §15).
func ArchivedFleetCardLoad(value *ArchivedFleetCard, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpen(data, report)
	report.Verdict = verdict
	report.Reason = ""
	if verdict == TableOpenRefused {
		report.Reason = "unsupported wire form"
		if len(data) > 0 && data[0] == 2 {
			report.Reason = "message form requires an announced vocabulary and a message reader"
		}
	}
	if verdict != TableOpenOk {
		ArchivedFleetCardReset(value)
		if verdict == TableOpenDamaged {
			report.Malformed = true
		}
		return false
	}
	// The root read answers its own early end after the walk, not before it.
	// A body that returned at its zero reference left the cursor on the byte
	// after that reference. Every field leaves the cursor where skip would, so
	// r.Offset != len(r.Buffer) is the old EndsEarly on the true path.
	// Nothing is decoded on the damaged path: the value goes back to defaults
	// and the report goes back to what the caller handed in, so an early end
	// counts no unknown, no kind mismatch and no clamp — as when the framing
	// walk refused before the reader had seen one byte.
	before := *report
	if !ArchivedFleetCardLoadBody(&r, value) {
		// The reading walk stops on rules the framing walk has no opinion about
		// — a reserved id in a file body is the one that matters — so a body
		// that stopped is still asked the framing question from the start of
		// the body, and a body whose framing ends early is damage whatever else
		// was wrong with it.
		probe := r
		probe.Offset = 0
		if probe.EndsEarly() {
			ArchivedFleetCardReset(value)
			*report = before
			report.Malformed = true
			report.Verdict = TableOpenDamaged
			return false
		}
		report.Verdict = TableOpenBodyStopped
		return false
	}
	if r.Offset != int64(len(r.Buffer)) {
		ArchivedFleetCardReset(value)
		*report = before
		report.Malformed = true
		report.Verdict = TableOpenDamaged
		return false
	}
	return true
}

