func SentinelEntryLoadBody(r *TableReader, value *SentinelEntry) bool {
	SentinelEntryReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x4f6a36d8e8907985: // stream
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Stream[:])
				value.StreamLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 128 {
				keep = tableUtf8Clamp(sub.Buffer, 128)
				r.Report.Clamped++
			}
			clear(value.Stream[:])
			copy(value.Stream[:keep], sub.Buffer)
			value.StreamLength = int32(keep)
		case 0xc341febe5aae51e5: // counts
			if kind != 13 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			SentinelCountsLoadBody(&sub, &value.Counts)
			if sub.Offset != int64(len(sub.Buffer)) {
				r.Report.Malformed = true
				SentinelCountsReset(&value.Counts)
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

