func RowCardsEntryLoadMessageBody(r *TableMessageReader, value *RowCardsEntry) bool {
	RowCardsEntryReset(value)
	for {
		ref, ok := r.Bits.Get(r.Vocabulary.RefBits)
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		entry, ok := r.Vocabulary.Entry(ref)
		if !ok || entry.Id >= 0xfffffffffffffffd {
			r.Report.Malformed = true
			return false
		}
		switch entry.Id {
		case 0x8a0bc1196111ad9b:
			{
				widened := false
				if entry.Shape.Kind != 12 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok || !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					start := r.Bits.Offset / 8
					if !r.Bits.Skip(int64(n) * 8) {
						r.Report.Malformed = true
						return false
					}
					text := r.Bits.Buffer[start : start+int64(n)]
					if !tableUtf8Valid(text) {
						r.Report.Malformed = true
						return false
					}
					kept := tableUtf8Clamp(text, min(int64(n), int64(135)))
					if kept < int64(n) {
						r.Report.Clamped++
					}
					clear(value.Row[:])
					copy(value.Row[:], text[:kept])
					value.RowLength = int32(kept)
				}
				if widened {
					r.Report.Widened++
				}
			}
		case 0xbad106a86ce7c7dc:
			{
				widened := false
				if entry.Shape.Kind != 14 || entry.Element.Kind != 13 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					base := &value.FieldCounts
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok {
						r.Report.Malformed = true
						return false
					}
					if entry.Element.Kind == 6 && !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					element := TableMessageEntry{Shape: entry.Element}
					_ = element
					keep := min(n, uint64(8))
					if keep < n {
						r.Report.Clamped++
					}
					walk := n
					if element.Shape.Bits >= 0 {
						walk = keep
					}
					for i := uint64(0); i < walk; i++ {
						var scratch RowFieldEntry
						p := &scratch
						if i < keep {
							p = &base[i]
						}
						if !RowFieldEntryLoadMessageBody(r, &(*p)) {
							return false
						}
					}
					if walk < n && !r.Bits.Skip(int64(n-walk)*element.Shape.Bits) {
						r.Report.Malformed = true
						return false
					}
					value.FieldCountsCount = int32(keep)
				}
				if widened {
					r.Report.Widened++
				}
			}
		default:
			r.Report.Unknown++
			if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}
func RowCardsEntryLoadMessages(values []RowCardsEntry, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !RowCardsEntryLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

