// the value already holds. The reader calls it before overlaying.
func FixStateEntryReset(value *FixStateEntry) {
	clear(value.Row[:])
	value.RowLength = 0
	for i := range value.ColCounts {
		ColCountEntryReset(&value.ColCounts[i])
	}
	value.ColCountsCount = 0
}

