	{
		if value.CauseLength < 0 || value.CauseLength > 64 {
			return false
		}
		if value.CauseLength > 0 {
			if ref := w.Ids.refAtHit(330, 0xb733af3b0d745380); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.CauseLength < 0 || value.CauseLength > 64 {
				return false
			}
			if !w.putLebPair(uint64(value.CauseLength)) {
				w.putLebWide(uint64(value.CauseLength))
			}
			w.Raw(value.Cause[:value.CauseLength])
		}
	}
