func DecisionDeliveryLoadMessages(values []DecisionDelivery, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !DecisionDeliveryLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// CoordinatorDeliveryReset restores CoordinatorDelivery's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func CoordinatorDeliveryReset(value *CoordinatorDelivery) {
	clear(value.CoveredBy[:])
	value.CoveredByLength = 0
	clear(value.From[:])
	value.FromLength = 0
	clear(value.To[:])
	value.ToLength = 0
	clear(value.Token[:])
	value.TokenLength = 0
	clear(value.Subject[:])
	value.SubjectLength = 0
	clear(value.Body[:])
	value.BodyLength = 0
	clear(value.Episode[:])
	value.EpisodeLength = 0
	value.Sent = false
	value.RetryBefore = 0
}

func CoordinatorDeliveryMeasureBody(value *CoordinatorDelivery, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !CoordinatorDeliverySaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func CoordinatorDeliveryMeasure(value *CoordinatorDelivery) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !CoordinatorDeliverySaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func CoordinatorDeliveryMeasureReason(value *CoordinatorDelivery) (int64, error) {
	size := CoordinatorDeliveryMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
