func SeatWaitsLoadMessages(values []SeatWaits, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !SeatWaitsLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// StopReset restores Stop's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func StopReset(value *Stop) {
	clear(value.Kind[:])
	value.KindLength = 0
	clear(value.Subject[:])
	value.SubjectLength = 0
	value.Since = 0
	clear(value.What[:])
	value.WhatLength = 0
	clear(value.Effect[:])
	value.EffectLength = 0
	clear(value.Undo[:])
	value.UndoLength = 0
	clear(value.Signal[:])
	value.SignalLength = 0
}

func StopMeasureBody(value *Stop, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !StopSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func StopMeasure(value *Stop) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !StopSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func StopMeasureReason(value *Stop) (int64, error) {
	size := StopMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
