func RefusedVerbLoadMessages(values []RefusedVerb, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !RefusedVerbLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// RefusedRecordReset restores RefusedRecord's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func RefusedRecordReset(value *RefusedRecord) {
	value.Epoch = 0
	for i := range value.Verbs {
		RefusedVerbReset(&value.Verbs[i])
	}
	value.VerbsCount = 0
	value.VerbPages = 0
}

func RefusedRecordMeasureBody(value *RefusedRecord, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !RefusedRecordSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func RefusedRecordMeasure(value *RefusedRecord) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !RefusedRecordSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func RefusedRecordMeasureReason(value *RefusedRecord) (int64, error) {
	size := RefusedRecordMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
