func RefusedRecordSaveMessageBody(w *TableMessageWriter, value *RefusedRecord) bool {
	{
		if value.Epoch != 0 {
			w.Put(36, TableMessageRefBitsHere)
			tableMessageWriteScalar(&w.TableBitWriter, TableMessageShape{Kind: 9, Packing: 0, Bits: 64, Base: [2]uint64{0x0, 0x0}, Min: 0, Max: 0, QMin: math.Float32frombits(0x0), QDelta: math.Float32frombits(0x0), QCount: 0}, uint64(value.Epoch), uint64(0))
		}
	}
	{
		if value.VerbsCount < 0 || value.VerbsCount > 8 {
			return false
		}
		if value.VerbsCount > 0 {
			w.Put(252, TableMessageRefBitsHere)
			if value.VerbsCount < 0 || value.VerbsCount > 8 {
				return false
			}
			w.Put(uint64(value.VerbsCount)-0, 4)
			for i := 0; i < int(value.VerbsCount); i++ {
				if !RefusedVerbSaveMessageBody(w, &value.Verbs[i]) {
					return false
				}
			}
		}
	}
	{
		if value.VerbPages != 0 {
			w.Put(253, TableMessageRefBitsHere)
			tableMessageWriteScalar(&w.TableBitWriter, TableMessageShape{Kind: 8, Packing: 0, Bits: 32, Base: [2]uint64{0x0, 0x0}, Min: 0, Max: 0, QMin: math.Float32frombits(0x0), QDelta: math.Float32frombits(0x0), QCount: 0}, uint64(value.VerbPages), uint64(0))
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func RefusedRecordMeasureMessages(values []*RefusedRecord, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !RefusedRecordSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func RefusedRecordSaveMessages(values []*RefusedRecord, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !RefusedRecordSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
