func RefusedRecordLoadMessages(values []RefusedRecord, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !RefusedRecordLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// LoadSampleReset restores LoadSample's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func LoadSampleReset(value *LoadSample) {
	value.At = 0
	value.Pct = 0.0
}

func LoadSampleMeasureBody(value *LoadSample, ids *TableIds) int64 {
	bytes := int64(1)
	if value.At != 0 {
		bytes += tableLebBytes(ids.refAtHit(14, 0x089c4e07b545a968)) + 1 + 8
	} // at
	if value.Pct != 0.0 {
		bytes += tableLebBytes(ids.refAtHit(225, 0x77c35c1956708830)) + 1 + 8
	} // pct
	if ids.Overflow {
		return -1
	}
	return bytes
}

func LoadSampleMeasure(value *LoadSample) int64 {
	var ids TableIds
	body := LoadSampleMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func LoadSampleMeasureReason(value *LoadSample) (int64, error) {
	size := LoadSampleMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func LoadSampleSaveBody(w *TableWriter, value *LoadSample) bool {
	{
		if value.At != 0 {
			if ref := w.Ids.refAtHit(14, 0x089c4e07b545a968); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			w.Put64(uint64(value.At))
		}
	}
	{
		if value.Pct != 0.0 {
			if ref := w.Ids.refAtHit(225, 0x77c35c1956708830); !w.headerPair(ref, 11) {
				w.headerRest(ref, 11)
			}
			w.Put64(math.Float64bits(value.Pct))
		}
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}

func LoadSampleSave(value *LoadSample, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !LoadSampleSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func LoadSampleLoadBody(r *TableReader, value *LoadSample) bool {
	LoadSampleReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x089c4e07b545a968: // at
			if kind != 5 {
				if tableKindWidens(kind, 5) {
					if !r.Has(tableKindBytes(kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := r.Signed(kind)
						value.At = int64(v)
					}
					r.Report.Widened++
					break
				}
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(8) {
				r.Report.Malformed = true
				return false
			}
			{
				v := int64(r.Get64())
				value.At = int64(v)
			}
		case 0x77c35c1956708830: // pct
			if kind != 11 {
				if tableKindWidens(kind, 11) {
					if !r.Has(tableKindBytes(kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						var v float64
						if kind == 10 {
							v = math.Float64frombits(tableWidenFloat(r.Get32()))
						} else {
							v = math.Float64frombits(r.Get64())
						}
						value.Pct = v
					}
					r.Report.Widened++
					break
				}
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(8) {
				r.Report.Malformed = true
				return false
			}
			{
				v := math.Float64frombits(r.Get64())
				value.Pct = v
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

// LoadSample also carries the FIXED form (form 3): LoadSampleFixedLoad reads that one and
// names a form-1 file `previous_form`. This Load is the VARIABLE form's entry
// point and reads form 1, whether or not the table was DECLARED fixed
// (docs/SPEC-TABLES.md §3.4, §15).
func LoadSampleLoad(value *LoadSample, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpen(data, report)
	report.Verdict = verdict
	report.Reason = ""
	if verdict == TableOpenRefused {
		report.Reason = "unsupported wire form"
		if len(data) > 0 && data[0] == 2 {
			report.Reason = "message form requires an announced vocabulary and a message reader"
		}
	}
	if verdict != TableOpenOk {
		LoadSampleReset(value)
		if verdict == TableOpenDamaged {
			report.Malformed = true
		}
		return false
	}
	// The root read answers its own early end after the walk, not before it.
	// A body that returned at its zero reference left the cursor on the byte
	// after that reference. Every field leaves the cursor where skip would, so
	// r.Offset != len(r.Buffer) is the old EndsEarly on the true path.
	// Nothing is decoded on the damaged path: the value goes back to defaults
	// and the report goes back to what the caller handed in, so an early end
	// counts no unknown, no kind mismatch and no clamp — as when the framing
	// walk refused before the reader had seen one byte.
	before := *report
	if !LoadSampleLoadBody(&r, value) {
		// The reading walk stops on rules the framing walk has no opinion about
		// — a reserved id in a file body is the one that matters — so a body
		// that stopped is still asked the framing question from the start of
		// the body, and a body whose framing ends early is damage whatever else
		// was wrong with it.
		probe := r
		probe.Offset = 0
		if probe.EndsEarly() {
			LoadSampleReset(value)
			*report = before
			report.Malformed = true
			report.Verdict = TableOpenDamaged
			return false
		}
		report.Verdict = TableOpenBodyStopped
		return false
	}
	if r.Offset != int64(len(r.Buffer)) {
		LoadSampleReset(value)
		*report = before
		report.Malformed = true
		report.Verdict = TableOpenDamaged
		return false
	}
	return true
}

