func MeterTicksLoadMessages(values []MeterTicks, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !MeterTicksLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// MeterHolderReset restores MeterHolder's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func MeterHolderReset(value *MeterHolder) {
	value.Pid = 0
	clear(value.Command[:])
	value.CommandLength = 0
	clear(value.User[:])
	value.UserLength = 0
	value.Open = 0
}

