func FriendReportLoadMessages(values []FriendReport, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !FriendReportLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// LiveSeenEntryReset restores LiveSeenEntry's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func LiveSeenEntryReset(value *LiveSeenEntry) {
	clear(value.Key[:])
	value.KeyLength = 0
	value.At = 0
}

