func CheckedCardSaveMessageBody(w *TableMessageWriter, value *CheckedCard) bool {
	{
		if value.IdLength < 0 || value.IdLength > 515 {
			return false
		}
		if value.IdLength > 0 {
			w.Put(14, TableMessageRefBitsHere)
			if value.IdLength < 0 || value.IdLength > 515 {
				return false
			}
			w.Put(uint64(value.IdLength), 10)
			w.Raw(value.Id[:value.IdLength])
		}
	}
	{
		if value.StreamLength < 0 || value.StreamLength > 128 {
			return false
		}
		if value.StreamLength > 0 {
			w.Put(45, TableMessageRefBitsHere)
			if value.StreamLength < 0 || value.StreamLength > 128 {
				return false
			}
			w.Put(uint64(value.StreamLength), 8)
			w.Raw(value.Stream[:value.StreamLength])
		}
	}
	{
		if value.TierLength < 0 || value.TierLength > 32 {
			return false
		}
		if value.TierLength > 0 {
			w.Put(46, TableMessageRefBitsHere)
			if value.TierLength < 0 || value.TierLength > 32 {
				return false
			}
			w.Put(uint64(value.TierLength), 6)
			w.Raw(value.Tier[:value.TierLength])
		}
	}
	{
		if value.PriorityLength < 0 || value.PriorityLength > 16 {
			return false
		}
		if value.PriorityLength > 0 {
			w.Put(47, TableMessageRefBitsHere)
			if value.PriorityLength < 0 || value.PriorityLength > 16 {
				return false
			}
			w.Put(uint64(value.PriorityLength), 5)
			w.Raw(value.Priority[:value.PriorityLength])
		}
	}
	{
		if value.NeedsLength < 0 || value.NeedsLength > 128 {
			return false
		}
		if value.NeedsLength > 0 {
			w.Put(48, TableMessageRefBitsHere)
			if value.NeedsLength < 0 || value.NeedsLength > 128 {
				return false
			}
			w.Put(uint64(value.NeedsLength), 8)
			w.Raw(value.Needs[:value.NeedsLength])
		}
	}
	{
		if value.BriefLength < 0 || value.BriefLength > 64 {
			return false
		}
		if value.BriefLength > 0 {
			w.Put(49, TableMessageRefBitsHere)
			if value.BriefLength < 0 || value.BriefLength > 64 {
				return false
			}
			w.Put(uint64(value.BriefLength), 7)
			w.Raw(value.Brief[:value.BriefLength])
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func CheckedCardMeasureMessages(values []*CheckedCard, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !CheckedCardSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func CheckedCardSaveMessages(values []*CheckedCard, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !CheckedCardSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
