func ResetMarkLoadMessages(values []ResetMark, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !ResetMarkLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// ResetResultReset restores ResetResult's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ResetResultReset(value *ResetResult) {
	ResetMarkReset(&value.Mark)
	ResetMarkReset(&value.Replaced)
	value.ReplacedPresent = false
	value.DryRun = false
	value.Replay = false
	for i := range value.Said {
		Prose256Reset(&value.Said[i])
	}
	value.SaidCount = 0
	clear(value.Refused[:])
	value.RefusedLength = 0
}

func ResetResultMeasureBody(value *ResetResult, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !ResetResultSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func ResetResultMeasure(value *ResetResult) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !ResetResultSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func ResetResultMeasureReason(value *ResetResult) (int64, error) {
	size := ResetResultMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
