						if !ok {
							r.Report.Malformed = true
							break
						}
						Prose256LoadBody(&elem, &value.Said[i])
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							Prose256Reset(&value.Said[i])
						}
						decoded = int32(i + 1)
