			keep := int64(len(sub.Buffer))
			if keep > 128 {
				keep = tableUtf8Clamp(sub.Buffer, 128)
				r.Report.Clamped++
			}
			clear(value.Refused[:])
			copy(value.Refused[:keep], sub.Buffer)
