func StreamBaseLoadMessages(values []StreamBase, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !StreamBaseLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// StreamBaseEntryReset restores StreamBaseEntry's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func StreamBaseEntryReset(value *StreamBaseEntry) {
	clear(value.Stream[:])
	value.StreamLength = 0
	StreamBaseReset(&value.StreamBase)
}

func StreamBaseEntryMeasureBody(value *StreamBaseEntry, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !StreamBaseEntrySaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func StreamBaseEntryMeasure(value *StreamBaseEntry) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !StreamBaseEntrySaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

