func StatsRecordSaveMessageBody(w *TableMessageWriter, value *StatsRecord) bool {
	{
		if value.Epoch != 0 {
			w.Put(36, TableMessageRefBitsHere)
			tableMessageWriteScalar(&w.TableBitWriter, TableMessageShape{Kind: 9, Packing: 0, Bits: 64, Base: [2]uint64{0x0, 0x0}, Min: 0, Max: 0, QMin: math.Float32frombits(0x0), QDelta: math.Float32frombits(0x0), QCount: 0}, uint64(value.Epoch), uint64(0))
		}
	}
	{
		if value.Since != 0 {
			w.Put(174, TableMessageRefBitsHere)
			tableMessageWriteScalar(&w.TableBitWriter, TableMessageShape{Kind: 5, Packing: 0, Bits: 64, Base: [2]uint64{0x0, 0x0}, Min: 0, Max: 0, QMin: math.Float32frombits(0x0), QDelta: math.Float32frombits(0x0), QCount: 0}, uint64(value.Since), uint64(0))
		}
	}
	{
		if value.ReasonLength < 0 || value.ReasonLength > 128 {
			return false
		}
		if value.ReasonLength > 0 {
			w.Put(106, TableMessageRefBitsHere)
			if value.ReasonLength < 0 || value.ReasonLength > 128 {
				return false
			}
			w.Put(uint64(value.ReasonLength), 8)
			w.Raw(value.Reason[:value.ReasonLength])
		}
	}
	{
		if value.ByLength < 0 || value.ByLength > 128 {
			return false
		}
		if value.ByLength > 0 {
			w.Put(37, TableMessageRefBitsHere)
			if value.ByLength < 0 || value.ByLength > 128 {
				return false
			}
			w.Put(uint64(value.ByLength), 8)
			w.Raw(value.By[:value.ByLength])
		}
	}
	{
		if value.KindsCount < 0 || value.KindsCount > 4 {
			return false
		}
		if value.KindsCount > 0 {
			w.Put(329, TableMessageRefBitsHere)
			if value.KindsCount < 0 || value.KindsCount > 4 {
				return false
			}
			w.Put(uint64(value.KindsCount)-0, 3)
			for i := 0; i < int(value.KindsCount); i++ {
				if !KindTimeEntrySaveMessageBody(w, &value.Kinds[i]) {
					return false
				}
			}
		}
	}
	{
		if value.StreamsCount < 0 || value.StreamsCount > 4 {
			return false
		}
		if value.StreamsCount > 0 {
			w.Put(39, TableMessageRefBitsHere)
			if value.StreamsCount < 0 || value.StreamsCount > 4 {
				return false
			}
			w.Put(uint64(value.StreamsCount)-0, 3)
			for i := 0; i < int(value.StreamsCount); i++ {
				if !StreamBaseEntrySaveMessageBody(w, &value.Streams[i]) {
					return false
				}
			}
		}
	}
	{
		if value.ArchivesCount < 0 || value.ArchivesCount > 4 {
			return false
		}
		if value.ArchivesCount > 0 {
			w.Put(334, TableMessageRefBitsHere)
			if value.ArchivesCount < 0 || value.ArchivesCount > 4 {
				return false
			}
			w.Put(uint64(value.ArchivesCount)-0, 3)
			for i := 0; i < int(value.ArchivesCount); i++ {
				if !Stamp80SaveMessageBody(w, &value.Archives[i]) {
					return false
				}
			}
		}
	}
	{
		if value.ResetMarkPresent {
			if true {
				w.Put(335, TableMessageRefBitsHere)
				if !ResetMarkSaveMessageBody(w, &value.ResetMark) {
					return false
				}
			}
		}
	}
	{
		if value.TidyingPresent {
			if true {
				w.Put(336, TableMessageRefBitsHere)
				if !TidyInFlightSaveMessageBody(w, &value.Tidying) {
					return false
				}
			}
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func StatsRecordMeasureMessages(values []*StatsRecord, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !StatsRecordSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func StatsRecordSaveMessages(values []*StatsRecord, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !StatsRecordSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
