// TidyRowReset restores TidyRow's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func TidyRowReset(value *TidyRow) {
	clear(value.Row[:])
	value.RowLength = 0
	value.Ok = 0
	value.Failed = 0
	for i := range value.Moved {
		TidyCardReset(&value.Moved[i])
	}
	value.MovedCount = 0
	for i := range value.Kept {
		TidyCardReset(&value.Kept[i])
	}
	value.KeptCount = 0
}

