func TidyRowLoadMessages(values []TidyRow, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !TidyRowLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// RoutePricesReset restores RoutePrices's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func RoutePricesReset(value *RoutePrices) {
	clear(value.Input[:])
	value.InputLength = 0
	clear(value.CacheRead[:])
	value.CacheReadLength = 0
	clear(value.CacheWrite[:])
	value.CacheWriteLength = 0
	clear(value.Output[:])
	value.OutputLength = 0
	value.ReasoningAsOutput = false
	value.LongContext = 0
	clear(value.InputLong[:])
	value.InputLongLength = 0
	clear(value.OutputLong[:])
	value.OutputLongLength = 0
	clear(value.Request[:])
	value.RequestLength = 0
	clear(value.Billing[:])
	value.BillingLength = 0
	clear(value.GatewayPercent[:])
	value.GatewayPercentLength = 0
	clear(value.Source[:])
	value.SourceLength = 0
	clear(value.AsOf[:])
	value.AsOfLength = 0
}

func RoutePricesMeasureBody(value *RoutePrices, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !RoutePricesSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func RoutePricesMeasure(value *RoutePrices) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !RoutePricesSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func RoutePricesMeasureReason(value *RoutePrices) (int64, error) {
	size := RoutePricesMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
