func RoutePricesSave(value *RoutePrices, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !RoutePricesSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

