func RouteLoadMessages(values []Route, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !RouteLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// RouteStatReset restores RouteStat's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func RouteStatReset(value *RouteStat) {
	RouteReset(&value.Route)
	value.Pinned = false
	value.Attempts = 0
	value.Ok = 0
	value.Failed = 0
	value.ProviderFailures = 0
	clear(value.MeanWall[:])
	value.MeanWallLength = 0
	clear(value.RestedUntil[:])
	value.RestedUntilLength = 0
	clear(value.RestedFor[:])
	value.RestedForLength = 0
	clear(value.Balance[:])
	value.BalanceLength = 0
	clear(value.BalanceAt[:])
	value.BalanceAtLength = 0
}

func RouteStatMeasureBody(value *RouteStat, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !RouteStatSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func RouteStatMeasure(value *RouteStat) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !RouteStatSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func RouteStatMeasureReason(value *RouteStat) (int64, error) {
	size := RouteStatMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
