			w.Put(372, TableMessageRefBitsHere)
			tableMessageWriteScalar(&w.TableBitWriter, TableMessageShape{Kind: 4, Packing: 0, Bits: 32, Base: [2]uint64{0x0, 0x0}, Min: 0, Max: 0, QMin: math.Float32frombits(0x0), QDelta: math.Float32frombits(0x0), QCount: 0}, uint64(value.Moved), uint64(0))
