func StuckLoadMessages(values []Stuck, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !StuckLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// LogIndexEntryReset restores LogIndexEntry's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func LogIndexEntryReset(value *LogIndexEntry) {
	clear(value.Name[:])
	value.NameLength = 0
	for i := range value.Ids {
		StreamIDReset(&value.Ids[i])
	}
	value.IdsCount = 0
}

func LogIndexEntryMeasureBody(value *LogIndexEntry, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !LogIndexEntrySaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func LogIndexEntryMeasure(value *LogIndexEntry) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !LogIndexEntrySaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func LogIndexEntryMeasureReason(value *LogIndexEntry) (int64, error) {
	size := LogIndexEntryMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
