// LogIndexReset restores LogIndex's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func LogIndexReset(value *LogIndex) {
	clear(value.Cursor[:])
	value.CursorLength = 0
	for i := range value.Entries {
		LogIndexEntryReset(&value.Entries[i])
	}
	value.EntriesCount = 0
	value.IndexPages = 0
}

