func StopLeaseLoadMessages(values []StopLease, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !StopLeaseLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// MachineReset restores Machine's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func MachineReset(value *Machine) {
	clear(value.State[:])
	value.StateLength = 0
	value.Since = 0
	clear(value.Who[:])
	value.WhoLength = 0
	value.RunSeq = 0
	value.StopIssued = false
	for i := range value.StopDebt {
		StopLeaseReset(&value.StopDebt[i])
	}
	value.StopDebtCount = 0
	value.DebtPages = 0
	value.StoppedNs = 0
	for i := range value.Spans {
		SpanReset(&value.Spans[i])
	}
	value.SpansCount = 0
	clear(value.Cause[:])
	value.CauseLength = 0
	clear(value.Reason[:])
	value.ReasonLength = 0
	value.Until = 0
	clear(value.StartedIn[:])
	value.StartedInLength = 0
}

