func LaneQuietLoadMessages(values []LaneQuiet, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !LaneQuietLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// SuppressedReset restores Suppressed's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func SuppressedReset(value *Suppressed) {
	value.Epoch = 0
	value.N = 0
	value.Lane = 0
	value.Readers = 0
	value.Tier = 0
}

func SuppressedMeasureBody(value *Suppressed, ids *TableIds) int64 {
	bytes := int64(1)
	if value.Epoch != 0 {
		bytes += tableLebBytes(ids.refAtHit(467, 0xfc9697d1196e6ba6)) + 1 + 8
	} // epoch
	if value.N != 0 {
		bytes += tableLebBytes(ids.refAtHit(318, 0xaf63e34c8601f871)) + 1 + 4
	} // n
	if value.Lane != 0 {
		bytes += tableLebBytes(ids.refAtHit(3, 0x0460ddad9060af0f)) + 1 + 4
	} // lane
	if value.Readers != 0 {
		bytes += tableLebBytes(ids.refAtHit(241, 0x81027a1935117cdf)) + 1 + 4
	} // readers
	if value.Tier != 0 {
		bytes += tableLebBytes(ids.refAtHit(54, 0x1e6f84ef2eb65989)) + 1 + 4
	} // tier
	if ids.Overflow {
		return -1
	}
	return bytes
}

func SuppressedMeasure(value *Suppressed) int64 {
	var ids TableIds
	body := SuppressedMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func SuppressedMeasureReason(value *Suppressed) (int64, error) {
	size := SuppressedMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
