func HeartbeatLoadMessages(values []Heartbeat, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !HeartbeatLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// StringKVReset restores StringKV's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func StringKVReset(value *StringKV) {
	clear(value.Key[:])
	value.KeyLength = 0
	clear(value.Value[:])
	value.ValueLength = 0
}

func StringKVMeasureBody(value *StringKV, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !StringKVSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func StringKVMeasure(value *StringKV) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !StringKVSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func StringKVMeasureReason(value *StringKV) (int64, error) {
	size := StringKVMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func StringKVSaveBody(w *TableWriter, value *StringKV) bool {
	{
		if value.KeyLength < 0 || value.KeyLength > 32 {
			return false
		}
		if value.KeyLength > 0 {
			if ref := w.Ids.refAtHit(114, 0x3dc94a19365b10ec); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.KeyLength < 0 || value.KeyLength > 32 {
				return false
			}
			if !w.putLebPair(uint64(value.KeyLength)) {
				w.putLebWide(uint64(value.KeyLength))
			}
			w.Raw(value.Key[:value.KeyLength])
		}
	}
	{
		if value.ValueLength < 0 || value.ValueLength > 64 {
			return false
		}
		if value.ValueLength > 0 {
			if ref := w.Ids.refAtHit(234, 0x7ce4fd9430e80cea); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.ValueLength < 0 || value.ValueLength > 64 {
				return false
			}
			if !w.putLebPair(uint64(value.ValueLength)) {
				w.putLebWide(uint64(value.ValueLength))
			}
			w.Raw(value.Value[:value.ValueLength])
		}
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}

func StringKVSave(value *StringKV, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !StringKVSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func StringKVLoadBody(r *TableReader, value *StringKV) bool {
	StringKVReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x3dc94a19365b10ec: // key
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Key[:])
				value.KeyLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 32 {
				keep = tableUtf8Clamp(sub.Buffer, 32)
				r.Report.Clamped++
			}
			clear(value.Key[:])
			copy(value.Key[:keep], sub.Buffer)
			value.KeyLength = int32(keep)
		case 0x7ce4fd9430e80cea: // value
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Value[:])
				value.ValueLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 64 {
				keep = tableUtf8Clamp(sub.Buffer, 64)
				r.Report.Clamped++
			}
			clear(value.Value[:])
			copy(value.Value[:keep], sub.Buffer)
			value.ValueLength = int32(keep)
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

// StringKV also carries the FIXED form (form 3): StringKVFixedLoad reads that one and
// names a form-1 file `previous_form`. This Load is the VARIABLE form's entry
// point and reads form 1, whether or not the table was DECLARED fixed
// (docs/SPEC-TABLES.md §3.4, §15).
func StringKVLoad(value *StringKV, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpen(data, report)
	report.Verdict = verdict
	report.Reason = ""
	if verdict == TableOpenRefused {
		report.Reason = "unsupported wire form"
		if len(data) > 0 && data[0] == 2 {
			report.Reason = "message form requires an announced vocabulary and a message reader"
		}
	}
	if verdict != TableOpenOk {
		StringKVReset(value)
		if verdict == TableOpenDamaged {
			report.Malformed = true
		}
		return false
	}
	// The root read answers its own early end after the walk, not before it.
	// A body that returned at its zero reference left the cursor on the byte
	// after that reference. Every field leaves the cursor where skip would, so
	// r.Offset != len(r.Buffer) is the old EndsEarly on the true path.
	// Nothing is decoded on the damaged path: the value goes back to defaults
	// and the report goes back to what the caller handed in, so an early end
	// counts no unknown, no kind mismatch and no clamp — as when the framing
	// walk refused before the reader had seen one byte.
	before := *report
	if !StringKVLoadBody(&r, value) {
		// The reading walk stops on rules the framing walk has no opinion about
		// — a reserved id in a file body is the one that matters — so a body
		// that stopped is still asked the framing question from the start of
		// the body, and a body whose framing ends early is damage whatever else
		// was wrong with it.
		probe := r
		probe.Offset = 0
		if probe.EndsEarly() {
			StringKVReset(value)
			*report = before
			report.Malformed = true
			report.Verdict = TableOpenDamaged
			return false
		}
		report.Verdict = TableOpenBodyStopped
		return false
	}
	if r.Offset != int64(len(r.Buffer)) {
		StringKVReset(value)
		*report = before
		report.Malformed = true
		report.Verdict = TableOpenDamaged
		return false
	}
	return true
}

const StringKVLoadRetainBuilder = "StringKV: retention requires a region round trip through the VARIABLE form"
const StringKVSaveRetainMessages = "StringKV: retention requires a region round trip through the VARIABLE form"
const StringKVLoadRetainMessages = "StringKV: retention requires a region round trip through the VARIABLE form"
const StringKVLoadRetain = "StringKV: retention requires a variable root and its region directory"
const StringKVMeasureRetain = "StringKV: retention requires a variable root and its region directory"
const StringKVSaveRetain = "StringKV: retention requires a variable root and its region directory"

func StringKVCookMeasure(value *StringKV) int64 { return 192 }
func StringKVCookMeasureReason(value *StringKV) (int64, error) {
	return StringKVCookMeasure(value), nil
}
func StringKVCookFrom(value *StringKV, buffer []byte, order TableByteOrder) bool {
	return tableCookFixed(unsafe.Pointer(value), StringKVTableType(), buffer, order)
}
func StringKVSaveMessageBody(w *TableMessageWriter, value *StringKV) bool {
	{
		if value.KeyLength < 0 || value.KeyLength > 32 {
			return false
		}
		if value.KeyLength > 0 {
			w.Put(357, TableMessageRefBitsHere)
			if value.KeyLength < 0 || value.KeyLength > 32 {
				return false
			}
			w.Put(uint64(value.KeyLength), 6)
			w.Raw(value.Key[:value.KeyLength])
		}
	}
	{
		if value.ValueLength < 0 || value.ValueLength > 64 {
			return false
		}
		if value.ValueLength > 0 {
			w.Put(358, TableMessageRefBitsHere)
			if value.ValueLength < 0 || value.ValueLength > 64 {
				return false
			}
			w.Put(uint64(value.ValueLength), 7)
			w.Raw(value.Value[:value.ValueLength])
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func StringKVMeasureMessages(values []*StringKV, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !StringKVSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func StringKVSaveMessages(values []*StringKV, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !StringKVSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func StringKVLoadMessageBody(r *TableMessageReader, value *StringKV) bool {
	StringKVReset(value)
	for {
		ref, ok := r.Bits.Get(r.Vocabulary.RefBits)
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		entry, ok := r.Vocabulary.Entry(ref)
		if !ok || entry.Id >= 0xfffffffffffffffd {
			r.Report.Malformed = true
			return false
		}
		switch entry.Id {
		case 0x3dc94a19365b10ec:
			{
				widened := false
				if entry.Shape.Kind != 12 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok || !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					start := r.Bits.Offset / 8
					if !r.Bits.Skip(int64(n) * 8) {
						r.Report.Malformed = true
						return false
					}
					text := r.Bits.Buffer[start : start+int64(n)]
					if !tableUtf8Valid(text) {
						r.Report.Malformed = true
						return false
					}
					kept := tableUtf8Clamp(text, min(int64(n), int64(32)))
					if kept < int64(n) {
						r.Report.Clamped++
					}
					clear(value.Key[:])
					copy(value.Key[:], text[:kept])
					value.KeyLength = int32(kept)
				}
				if widened {
					r.Report.Widened++
				}
			}
		case 0x7ce4fd9430e80cea:
			{
				widened := false
				if entry.Shape.Kind != 12 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok || !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					start := r.Bits.Offset / 8
					if !r.Bits.Skip(int64(n) * 8) {
						r.Report.Malformed = true
						return false
					}
					text := r.Bits.Buffer[start : start+int64(n)]
					if !tableUtf8Valid(text) {
						r.Report.Malformed = true
						return false
					}
					kept := tableUtf8Clamp(text, min(int64(n), int64(64)))
					if kept < int64(n) {
						r.Report.Clamped++
					}
					clear(value.Value[:])
					copy(value.Value[:], text[:kept])
					value.ValueLength = int32(kept)
				}
				if widened {
					r.Report.Widened++
				}
			}
		default:
			r.Report.Unknown++
			if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}
func StringKVLoadMessages(values []StringKV, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !StringKVLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

