func FieldGuardSaveBody(w *TableWriter, value *FieldGuard) bool {
	var arrayLengths [1]int64
	if value.EqualsPresent {
		{
			mark := w.Ids.Count
			ref := w.Ids.refAtHit(91, 0x2fedf26ef08343d4)
			start := w.Ids.Count
			n := GuardTextMeasureBody(&value.Equals, w.Ids)
			if n < 0 || w.Ids.Overflow {
				return false
			}
			if true {
				if w.Measuring {
					w.Advance(tableLebBytes(ref) + 1 + tableLebBytes(uint64(n)) + n)
				} else {
					w.Ids.Truncate(start)
					if !w.headerPair(ref, 13) {
						w.headerRest(ref, 13)
					}
					if !w.putLebPair(uint64(n)) {
						w.putLebWide(uint64(n))
					}
					if !GuardTextSaveBody(w, &value.Equals) {
						return false
					}
				}
			} else {
				w.Ids.Truncate(mark)
			}
		}
	}
	if value.AbsentPresent {
		{
			if true {
				if ref := w.Ids.refAtHit(306, 0xa3d0dfc3e1dbb698); !w.headerPair(ref, 1) {
					w.headerRest(ref, 1)
				}
				if value.Absent {
					w.Put8(1)
				} else {
					w.Put8(0)
				}
			}
		}
	}
	{
		if value.OneOfCount < 0 || value.OneOfCount > 1 {
			return false
		}
		if value.OneOfCount > 0 {
			if ref := w.Ids.refAtHit(446, 0xf2a11d5df6c1be51); !w.headerPair(ref, 14) {
				w.headerRest(ref, 14)
			}
			if value.OneOfCount < 0 || value.OneOfCount > 1 {
				return false
			}
			{
				mark := w.Ids.Count
				payload405 := TableWriter{Measuring: true, Ids: w.Ids}
				pairs := uint64(0)
				for i := 0; i < int(value.OneOfCount); i++ {
					n := Word64MeasureBody(&value.OneOf[i], payload405.Ids)
					if n < 0 {
						return false
					}
					arrayLengths[i] = n
					if !payload405.putLebPair(uint64(n)) {
						payload405.putLebWide(uint64(n))
					}
					payload405.Advance(n)
					pairs++
				}
				if payload405.Overflow {
					return false
				}
				n := int64(1) + tableLebBytes(pairs) + payload405.Offset
				if !w.putLebPair(uint64(n)) {
					w.putLebWide(uint64(n))
				}
				if w.Measuring {
					w.Advance(n)
				} else {
					w.Ids.Truncate(mark)
					w.Put8(13)
					if !w.putLebPair(pairs) {
						w.putLebWide(pairs)
					}
					for i := 0; i < int(value.OneOfCount); i++ {
						if !w.putLebPair(uint64(arrayLengths[i])) {
							w.putLebWide(uint64(arrayLengths[i]))
						}
						if !Word64SaveBody(w, &value.OneOf[i]) {
							return false
						}
					}
				}
			}
		}
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}

