func TimerLoadMessages(values []Timer, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !TimerLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// TimersReset restores Timers's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func TimersReset(value *Timers) {
	for i := range value.OpenTimers {
		TimerReset(&value.OpenTimers[i])
	}
	value.OpenTimersCount = 0
}

func TimersMeasureBody(value *Timers, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !TimersSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func TimersMeasure(value *Timers) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !TimersSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func TimersMeasureReason(value *Timers) (int64, error) {
	size := TimersMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func TimersSaveBody(w *TableWriter, value *Timers) bool {
	var arrayLengths [1]int64
	{
		if value.OpenTimersCount < 0 || value.OpenTimersCount > 1 {
			return false
		}
		if value.OpenTimersCount > 0 {
			if ref := w.Ids.refAtHit(476, 0xfe3930a031d4a5f0); !w.headerPair(ref, 14) {
				w.headerRest(ref, 14)
			}
			if value.OpenTimersCount < 0 || value.OpenTimersCount > 1 {
				return false
			}
			{
				mark := w.Ids.Count
				payload451 := TableWriter{Measuring: true, Ids: w.Ids}
				pairs := uint64(0)
				for i := 0; i < int(value.OpenTimersCount); i++ {
					n := TimerMeasureBody(&value.OpenTimers[i], payload451.Ids)
					if n < 0 {
						return false
					}
					arrayLengths[i] = n
					if !payload451.putLebPair(uint64(n)) {
						payload451.putLebWide(uint64(n))
					}
					payload451.Advance(n)
					pairs++
				}
				if payload451.Overflow {
					return false
				}
				n := int64(1) + tableLebBytes(pairs) + payload451.Offset
				if !w.putLebPair(uint64(n)) {
					w.putLebWide(uint64(n))
				}
				if w.Measuring {
					w.Advance(n)
				} else {
					w.Ids.Truncate(mark)
					w.Put8(13)
					if !w.putLebPair(pairs) {
						w.putLebWide(pairs)
					}
					for i := 0; i < int(value.OpenTimersCount); i++ {
						if !w.putLebPair(uint64(arrayLengths[i])) {
							w.putLebWide(uint64(arrayLengths[i]))
						}
						if !TimerSaveBody(w, &value.OpenTimers[i]) {
							return false
						}
					}
				}
			}
		}
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}

func TimersSave(value *Timers, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !TimersSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func TimersLoadBody(r *TableReader, value *Timers) bool {
	TimersReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0xfe3930a031d4a5f0: // open_timers
			if kind != 14 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if len(sub.Buffer) >= 2 {
				header := sub
				header.Buffer = r.Buffer[r.Offset-int64(len(sub.Buffer)):]
				elemKind := header.Get8()
				count, ok := header.Leb()
				sub.Offset = header.Offset
				if !ok {
					r.Report.Malformed = true
				} else {
					if elemKind != 13 {
						r.Report.KindMismatch++
						break
					}
					keep := count
					if keep > 1 {
						keep = 1
						r.Report.Clamped++
					}
					previous := value.OpenTimersCount
					decoded := int32(0)
					for i := uint64(0); i < keep; i++ {
						elem, ok := sub.Body()
						if !ok {
							r.Report.Malformed = true
							break
						}
						TimerLoadBody(&elem, &value.OpenTimers[i])
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							TimerReset(&value.OpenTimers[i])
						}
						decoded = int32(i + 1)
					}
					for i := decoded; i < previous; i++ {
						TimerReset(&value.OpenTimers[i])
					}
					value.OpenTimersCount = decoded
				}
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

// Timers also carries the FIXED form (form 3): TimersFixedLoad reads that one and
// names a form-1 file `previous_form`. This Load is the VARIABLE form's entry
// point and reads form 1, whether or not the table was DECLARED fixed
// (docs/SPEC-TABLES.md §3.4, §15).
func TimersLoad(value *Timers, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpen(data, report)
	report.Verdict = verdict
	report.Reason = ""
	if verdict == TableOpenRefused {
		report.Reason = "unsupported wire form"
		if len(data) > 0 && data[0] == 2 {
			report.Reason = "message form requires an announced vocabulary and a message reader"
		}
	}
	if verdict != TableOpenOk {
		TimersReset(value)
		if verdict == TableOpenDamaged {
			report.Malformed = true
		}
		return false
	}
	// The root read answers its own early end after the walk, not before it.
	// A body that returned at its zero reference left the cursor on the byte
	// after that reference. Every field leaves the cursor where skip would, so
	// r.Offset != len(r.Buffer) is the old EndsEarly on the true path.
	// Nothing is decoded on the damaged path: the value goes back to defaults
	// and the report goes back to what the caller handed in, so an early end
	// counts no unknown, no kind mismatch and no clamp — as when the framing
	// walk refused before the reader had seen one byte.
	before := *report
	if !TimersLoadBody(&r, value) {
		// The reading walk stops on rules the framing walk has no opinion about
		// — a reserved id in a file body is the one that matters — so a body
		// that stopped is still asked the framing question from the start of
		// the body, and a body whose framing ends early is damage whatever else
		// was wrong with it.
		probe := r
		probe.Offset = 0
		if probe.EndsEarly() {
			TimersReset(value)
			*report = before
			report.Malformed = true
			report.Verdict = TableOpenDamaged
			return false
		}
		report.Verdict = TableOpenBodyStopped
		return false
	}
	if r.Offset != int64(len(r.Buffer)) {
		TimersReset(value)
		*report = before
		report.Malformed = true
		report.Verdict = TableOpenDamaged
		return false
	}
	return true
}

