func SeatChangeLoadMessages(values []SeatChange, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !SeatChangeLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// HeldRecordReset restores HeldRecord's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func HeldRecordReset(value *HeldRecord) {
	clear(value.Id[:])
	value.IdLength = 0
	value.HeldLock = false
	clear(value.Verb[:])
	value.VerbLength = 0
	value.At = 0
	for i := range value.Manifests {
		BatchManifestReset(&value.Manifests[i])
	}
	value.ManifestsCount = 0
	value.ManifestPages = 0
	for i := range value.Notes {
		NoteReset(&value.Notes[i])
	}
	value.NotesCount = 0
	value.NotePages = 0
	for i := range value.Decided {
		NoteReset(&value.Decided[i])
	}
	value.DecidedCount = 0
	value.DecidedPages = 0
	for i := range value.Log {
		LogLineReset(&value.Log[i])
	}
	value.LogCount = 0
	value.LogPages = 0
	for i := range value.Updates {
		NoteReset(&value.Updates[i])
	}
	value.UpdatesCount = 0
	value.UpdatePages = 0
	for i := range value.Closes {
		Word64Reset(&value.Closes[i])
	}
	value.ClosesCount = 0
	for i := range value.Streams {
		MemberNameReset(&value.Streams[i])
	}
	value.StreamsCount = 0
	clear(value.CallerOp[:])
	value.CallerOpLength = 0
	clear(value.Result[:])
	value.ResultLength = 0
	clear(value.Stuck[:])
	value.StuckLength = 0
	for i := range value.Queue {
		QueuedChangeReset(&value.Queue[i])
	}
	value.QueueCount = 0
	value.QueuePages = 0
	value.Drain = 0
	SeatChangeReset(&value.Seat)
	value.SeatPresent = false
	for i := range value.CloseTimers {
		Word64Reset(&value.CloseTimers[i])
	}
	value.CloseTimersCount = 0
	TimersReset(&value.Timers)
	value.TimersPresent = false
}

func HeldRecordMeasureBody(value *HeldRecord, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !HeldRecordSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func HeldRecordMeasure(value *HeldRecord) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !HeldRecordSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func HeldRecordMeasureReason(value *HeldRecord) (int64, error) {
	size := HeldRecordMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
